  const actualWard=Reflect.get(w,'grantAbsorb'),record=(mark:string)=>poisonFn(function(this:World,...args:Parameters<typeof host.grantAbsorb>){assert.equal(this,w);events.push(mark);const value=Reflect.apply(actualWard,this,args);if(fail)throw Error('after actual ward');return value;});Reflect.set(w,'grantAbsorb',record('selected'));const selected=host.grantAbsorb;Reflect.set(w,'grantAbsorb',record('live'));if(fail){assert.throws(()=>selected(c,3,2),/after actual ward/);assert.throws(()=>host.grantAbsorb(c,4,2),/after actual ward/);}else{selected(c,3,2);host.grantAbsorb(c,4,2);}assert.deepEqual(events.slice(-2),['selected','live']);c.mana=20;c.sheet.setSource('payment ward',[mod('costWard_mana','flat',1)]);if(fail)assert.throws(()=>worldCall(w,'paySkillCost',c,i,{mana:10,life:0}),/after actual ward/);else worldCall(w,'paySkillCost',c,i,{mana:10,life:0});assert.equal(c.mana,10);assert.ok(c.absorb>=10);assert.equal(applyReads,0);
